{\small
\resumeSubHeadingListStart

\resumeSubheading
  {Machine Learning Engineer Intern}{May 2025 -- August 2025}
  {Ayar Labs}{Santa Clara, CA}
  \resumeItemListStart
    \resumeItem{Measured signal processing time-frequency separability on labeled transient audio clips by running FFT-based spectrogram variants in Python notebooks and comparing windowing choices against a held-out set.}
    \resumeItem{Created a denoising filter module using FIR filters and IIR filter design in Python, then validated frequency-response behavior with synthetic noise plus recorded clips.}
    \resumeItem{Trained a CNN on cropped visual frames and integrated it with temporal aggregation to support end-to-end gunshot detection, tuning loss to handle class imbalance across modalities.}
  \resumeItemListEnd

\resumeSubheading
  {Machine Learning Research Intern}{July 2024 -- December 2024}
  {Indian Institute of Technology, Indore}{Indore, India}
  \resumeItemListStart
    \resumeItem{Developed a Python DFT training pipeline that converts raw sensor inputs into fixed-shape tensors via framing, normalization, augmentation, and reproducible train/val/test splits.}
    \resumeItem{Analyzed model performance using statistical pattern processing baselines and complementary methods, including support vector machines and Wiener filtering, to qualitatively assess reliability and robustness.}
    \resumeItem{Accelerated near-real-time inference by tuning preprocessing and algorithms in a PyTorch inference script, adjusting window hop size and batching, then verified end-to-end latency with repeatable Linux timing tests.}
  \resumeItemListEnd

\resumeSubheading
  {Machine Learning Research Intern}{January 2024 -- June 2024}
  {National Institute of Technology, Jaipur}{Jaipur, India}
  \resumeItemListStart
    \resumeItem{Released dockerized inference services that consumed audio streams, ran trained gunshot detection models, and produced event outputs for downstream alerting from NIT Jaipur, which cut rollback time by roughly ~fr.}
    \resumeItem{Wrote pytest-based automated tests and validation checks for preprocessing correctness and model inference outputs, which reduced the update process from roughly 25 steps to 6 at National Institute of Technology.}
    \resumeItem{Logged experiment tracking at NIT Jaipur to iterate on machine learning model and signal processing designs, comparing runs, analyzing errors, and refining preprocessing and design choices.}
  \resumeItemListEnd

\resumeSubheading
  {Machine Learning Research Intern}{May 2023 -- December 2023}
  {Indian Institute of Technology, Indore}{Indore, India}
  \resumeItemListStart
    \resumeItem{Automated work with Linux environments to run training and inference jobs, manage dependencies, and troubleshoot performance or runtime issues, which saved the team about 6 hours a week each week.}
    \resumeItem{Supported engineers by integrating audio and visual detection components into emergency response automation workflows using detection and event APIs, enabling roughly real-time detection and event triggering.}
    \resumeItem{Explored speech recognition and audio modeling with RNNs at IIT Indore, which improved robustness to noisy, reverberant inputs after validating the approach across diverse experimental conditions.}
  \resumeItemListEnd

\resumeSubHeadingListEnd

